// Flat burger illustration: burger(bun, patty, sauce)
function burger(bun,patty,sauce){return `<svg viewBox="0 0 120 106" aria-hidden="true"><path d="M10 46C10 12 110 12 110 46Z" fill="${bun}"/><g fill="#fff8"><ellipse cx="40" cy="26" rx="4" ry="2"/><ellipse cx="62" cy="20" rx="4" ry="2"/><ellipse cx="82" cy="28" rx="4" ry="2"/></g><path d="M8 48q8 8 16 0t16 0 16 0 16 0 16 0 16 0v4H8Z" fill="#4a9a54"/><path d="M12 54h96l-8 10H20Z" fill="#f2b01e"/><rect x="10" y="62" width="100" height="16" rx="8" fill="${patty}"/><path d="M14 78q10 10 20 0t20 0 20 0 20 0 14 0v4H14Z" fill="${sauce}"/><path d="M10 84h100v6q0 10-14 10H24q-14 0-14-10Z" fill="${bun}"/></svg>`}
document.querySelectorAll('[data-b]').forEach(e=>e.innerHTML=burger(...e.dataset.b.split(',')));
// Menu photos (embedded)
const PICS={"aloo": "data:image/webp;base64,", "paneer": "data:image/webp;base64,", "crunch": "data:image/webp;base64,", "mushroom": "data:image/webp;base64,", "peri": "data:image/webp;base64,"};
document.querySelectorAll('[data-img]').forEach(e=>{e.innerHTML=`<img src="${PICS[e.dataset.img]}" alt="${e.dataset.alt||''}">`});
// Exploded 3D burger scene: real photo cut into layers (images embedded, no folder needed)
const IMG={"bun": "data:image/webp;base64,", "lettuce": "data:image/webp;base64,", "tomato": "data:image/webp;base64,", "onion": "data:image/webp;base64,", "cheese": "data:image/webp;base64,", "patty": "data:image/webp;base64,", "fill": "data:image/webp;base64,", "base": "data:image/webp;base64,"};
const LAYERS=[["bun", 16.8, 0.2, 68.03, 29.78], ["lettuce", 16.67, 17.08, 67.58, 24.48], ["tomato", 23.76, 23.59, 53.52, 20.38], ["onion", 24.02, 33.8, 49.61, 16.72], ["cheese", 19.73, 37.53, 60.55, 13.43], ["patty", 23.11, 45.23, 53.78, 8.99], ["fill", 17.84, 56.63, 67.32, 2.02], ["base", 1.04, 69.78, 97.72, 0]]; // [name, left%, top%, width%, collapsed shift%]
document.querySelectorAll('[data-scene]').forEach(s=>{
 s.innerHTML='<div class="stack">'+LAYERS.map(([n,l,t,w,dy],i)=>
  `<img class="layer ${n=='base'?'static':''}" src="${IMG[n]}" alt="" style="left:${l}%;top:${t}%;width:${w}%;--i:${LAYERS.length-i};--dy:${dy};--r:${(i%2?1:-1)*(1+i%3)};--dl:${(i*.07).toFixed(2)}s;--a:${(i%2?-1:1)*(3+i%3*2)}">`).join('')+'</div>';
 const st=s.firstChild;s._st=st;
 const size=()=>st.style.setProperty('--H',s.offsetHeight/100+'px');size();addEventListener('resize',size);
 setTimeout(()=>st.classList.add('open'),500)});
const calm=matchMedia('(prefers-reduced-motion:reduce)').matches;
if(!calm){
 addEventListener('mousemove',e=>{const x=e.clientX/innerWidth-.5,y=e.clientY/innerHeight-.5;
  document.querySelectorAll('[data-scene]').forEach(s=>{s._st.style.setProperty('--rx',x*28+'deg');s._st.style.setProperty('--ry',y*-14+'deg')})});
 document.querySelectorAll('.art').forEach(a=>{const c=a.firstElementChild;
  a.addEventListener('mousemove',e=>{const r=a.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.transform=`rotateY(${x*22}deg) rotateX(${-y*22}deg)`});
  a.addEventListener('mouseleave',()=>c.style.transform='')});
 const sp=[...document.querySelectorAll('[data-speed]')];
 addEventListener('scroll',()=>sp.forEach(e=>e.style.transform=`translateY(${scrollY*e.dataset.speed}px)`),{passive:true});
}
